 \\u0911\\u092a\\u094d\\u0938 \\u0915\\u093e \\u0905\\u0928\\u0941\\u092a\\u093e\\u0924\\u0964\\n* **\\u0917\\u094d\\u0930\\u093e\\u092b\\u0935\\u093f\\u091c\\u093c \\u0932\\u0947\\u0906\\u0909\\u091f \\u092e\\u0947\\u091f\\u094d\\u0930\\u093f\\u0915\\u094d\\u0938:** \\u090f\\u091c \\u0915\\u094d\\u0930\\u0949\\u0938\\u093f\\u0902\\u0917 \\u0915\\u0940 \\u0938\\u0902\\u0916\\u094d\\u092f\\u093e (Edge Crossings) \\u0914\\u0930 \\u0935\\u093f\\u091c\\u093c\\u0941\\u0905\\u0932 \\u0921\\u0947\\u0902\\u0938\\u093f\\u091f\\u0940 (TorchViz \\u0930\\u0947\\u0902\\u0921\\u0930\\u093f\\u0902\\u0917 \\u092e\\u0947\\u0902)\\u0964\\n\\n#### (\\u0916) \\u0935\\u094d\\u092f\\u093e\\u0916\\u094d\\u092f\\u093e\\u0924\\u094d\\u092e\\u0915\\u0924\\u093e \\u092e\\u0947\\u091f\\u094d\\u0930\\u093f\\u0915\\u094d\\u0938 (Interpretability & Usability Metrics)\\n* **\\u0938\\u093f\\u092e\\u0947\\u0902\\u091f\\u093f\\u0915 \\u092e\\u0949\\u0921\\u094d\\u092f\\u0941\\u0932\\u0948\\u0930\\u093f\\u091f\\u0940 (Semantic Modularity):** \\u0915\\u094d\\u092f\\u093e \\u0917\\u094d\\u0930\\u093e\\u092b \\u092e\\u0949\\u0921\\u0932 \\u092b\\u0949\\u0930\\u0935\\u0930\\u094d\\u0921 \\u092a\\u093e\\u0938 \\u0914\\u0930 \\u0911\\u092a\\u094d\\u091f\\u093f\\u092e\\u093e\\u0907\\u091c\\u093c\\u0930 \\u0905\\u092a\\u0921\\u0947\\u091f \\u0938\\u094d\\u091f\\u0947\\u091f\\u094d\\u0938 ($m_t, v_t$) \\u0915\\u094b \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u0930\\u0942\\u092a \\u0938\\u0947 \\u0905\\u0932\\u0917 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948?\\n* **\\u0939\\u094d\\u092f\\u0942\\u092e\\u0928-\\u0907\\u0928-\\u0926-\\u0932\\u0942\\u092a \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0905\\u0927\\u094d\\u092f\\u092f\\u0928 (User Study):** \\u090f\\u092e\\u090f\\u0932 \\u0936\\u094b\\u0927\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902/\\u0907\\u0902\\u091c\\u0940\\u0928\\u093f\\u092f\\u0930\\u094b\\u0902 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u090f\\u0915 \\u0928\\u0