e\\u093e\\u0928\\u093e\\u0902\\u0924\\u0930 \\u0930\\u0942\\u092a \\u0938\\u0947 TorchViz \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0935\\u093f\\u091c\\u093c\\u0941\\u0905\\u0932\\u093e\\u0907\\u091c\\u093c\\u0947\\u0936\\u0928 \\u092c\\u0928\\u093e\\u0928\\u093e\\u0964\\n3. **\\u092e\\u0948\\u091f\\u094d\\u0930\\u093f\\u0915\\u094d\\u0938 \\u0938\\u0902\\u0915\\u0932\\u0928 \\u0914\\u0930 \\u0938\\u094d\\u0915\\u0947\\u0932\\u093f\\u0902\\u0917 \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923:** $T$ \\u0938\\u094d\\u091f\\u0947\\u092a\\u094d\\u0938 \\u092c\\u0922\\u093c\\u0928\\u0947 \\u092a\\u0930 \\u091c\\u091f\\u093f\\u0932\\u0924\\u093e \\u0915\\u0947 \\u0917\\u094d\\u0930\\u094b\\u0925 \\u0930\\u0947\\u091f ($\\\\mathcal{O}(T)$ \\u092f\\u093e $\\\\mathcal{O}(P \\\\times T)$) \\u0915\\u0940 \\u0924\\u0941\\u0932\\u0928\\u093e \\u0915\\u0930\\u0928\\u093e\\u0964\\n4. **\\u0935\\u094d\\u092f\\u093e\\u0916\\u094d\\u092f\\u093e\\u0924\\u094d\\u092e\\u0915\\u0924\\u093e \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 \\u0935 \\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928:** \\u091f\\u0940-\\u091f\\u0947\\u0938\\u094d\\u091f/ANOVA \\u0915\\u0947 \\u092e\\u093e\\u0927\\u094d\\u092f\\u092e \\u0938\\u0947 \\u092e\\u093e\\u0924\\u094d\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092e\\u0947\\u091f\\u094d\\u0930\\u093f\\u0915\\u094d\\u0938 \\u0914\\u0930 \\u0909\\u092a\\u092f\\u094b\\u0917\\u0915\\u0930\\u094d\\u0924\\u093e \\u0905\\u0927\\u094d\\u092f\\u092f\\u0928 \\u0915\\u0947 \\u092a\\u0930\\u093f\\u0923\\u093e\\u092e\\u094b\\u0902 \\u0915\\u093e \\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923\\u0964\\n\\n---\\n\\n\\u0915\\u0943\\u092a\\u092f\\u093e \\u0907\\u0938 \\u0926\\u0943\\u0937\\u094d\\u091f\\u093f\\u0915\\u094b\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0