2f\\u094b\\u0917\\u094d\\u092f \\u0935\\u0948\\u091c\\u094d\\u091e\\u093e\\u0928\\u093f\\u0915 \\u092e\\u093e\\u0928\\u0926\\u0902\\u0921 \\u0938\\u094d\\u0925\\u093e\\u092a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948\\u0964 \\u0905\\u092a\\u0947\\u0915\\u094d\\u0937\\u093f\\u0924 \\u092a\\u0930\\u093f\\u0923\\u093e\\u092e \\u092f\\u0939 \\u0938\\u093f\\u0926\\u094d\\u0927 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947 \\u0915\\u093f TorchOpt \\u092e\\u0947\\u0902 Adam \\u0915\\u093e \\u092b\\u094d\\u092f\\u0942\\u091c\\u093c\\u0928 \\u0928 \\u0915\\u0947\\u0935\\u0932 \\u0911\\u091f\\u094b\\u0917\\u094d\\u0930\\u093e\\u0921 \\u0917\\u094d\\u0930\\u093e\\u092b \\u0915\\u0947 \\u0906\\u0915\\u093e\\u0930 ($|V|, |E|$) \\u0915\\u094b $75\\\\text{\\u2013}85\\\\%$ \\u0924\\u0915 \\u0938\\u0902\\u0915\\u0941\\u091a\\u093f\\u0924 \\u0915\\u0930\\u0924\\u093e \\u0939\\u0948, \\u092c\\u0932\\u094d\\u0915\\u093f \\u092f\\u0939 \\u0935\\u093f\\u091c\\u093c\\u0941\\u0905\\u0932 \\u0915\\u094d\\u0932\\u091f\\u0930 (\\u090f\\u091c \\u0915\\u094d\\u0930\\u0949\\u0938\\u093f\\u0902\\u0917\\u094d\\u0938) \\u0915\\u094b \\u0928\\u094d\\u092f\\u0942\\u0928\\u0924\\u092e \\u0915\\u0930\\u0915\\u0947 \\u0914\\u0930 \\u0911\\u092a\\u0930\\u0947\\u091f\\u0930\\u094b\\u0902 \\u0915\\u094b \\u0938\\u093e\\u0930\\u094d\\u0925\\u0915 \\u0938\\u093f\\u092e\\u0947\\u0902\\u091f\\u093f\\u0915 \\u092e\\u0949\\u0921\\u094d\\u092f\\u0942\\u0932 \\u092e\\u0947\\u0902 \\u0938\\u092e\\u0942\\u0939\\u093f\\u0924 \\u0915\\u0930\\u0915\\u0947 TorchViz \\u0935\\u093f\\u091c\\u093c\\u0941\\u0905\\u0932\\u093e\\u0907\\u091c\\u093c\\u0947\\u0936\\u0928 \\u0915\\u0940 \\u0935\\u094d\\u092f\\u093e\\u0916\\u094d\\u092f\\u093e\\u0924\\u094d\\u092e\\u0915\\u0924\\u093e \\u092e\\u0947\\u0902 \\u0915\\u094d\\u0930\\u093e\\u0902\\u0924\\u093f\\u0915\\u093e\\u0930\\u0940 \\u0938\\u0941\\u0927\\u093e\\u0930 \\u0932\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964\", \"assumptions\": [\"PyTorch \\u0911\\u091f\\u094